test('legacy replacement retains referenced omissions without archiving',()=>{const s=importFixture();s.contractors.push({id:'FREE',name:'ไม่ใช้งาน',code:'C000005'});const preview=App.previewMasterCSV(s,'contractors','ชื่อ\nใหม่');const result=App.replaceMasterCSV(s,'contractors',preview);assert.equal(result.archived,0);assert.equal(result.removed,1);assert(s.contractors.some(x=>x.name==='ก'&&!x.archived));assert(s.contractors.some(x=>x.name==='ใหม่'));assert(!s.contractors.some(x=>x.id==='FREE'));});
test('replacing registry CSV stays within funding/year and preserves closed snapshots',()=>{const s=importFixture();s.projects.push({...clone(s.projects[0]),id:'OTHER',contract:'2/2569',funding:'PROVINCE'});normalizeState(s);const before=JSON.stringify(s.reports);const rows=[{contract:'3/2569',title:'ใหม่',start:'2026-01-01',end:'2026-03-31',duration:90}];const preview=App.previewRegistryImport(s,rows,2569,'DOH');const result=App.replaceRegistryCSV(s,preview);assert.equal(result.removed,1);assert.equal(JSON.stringify(result.state.reports),before);assert(result.state.contractRegistry.some(x=>x.funding==='PROVINCE'&&!x.archived));assert(result.state.projects.find(x=>x.id==='LEGACY-P').deletedAt);});

