// v8 user journeys: readable CSV identity, contacts, legacy compatibility and one-to-one work codes.
test('contractor CSV carries contacts and readable identity while preserving internal links',()=>{const s=importFixture();App.assignMasterCodes(s);const old=s.contractors[0],id=old.id,code=old.code;const p=App.previewMasterCSV(s,'contractors',`รหัส,ชื่อผู้รับจ้าง,ที่อยู่,เบอร์โทรศัพท์\n${code},ชื่อปรับใหม่,"ที่อยู่, ไทย",0123456789`);assert.deepEqual(p[0].errors,[]);App.applyMasterCSV(s,'contractors',p,{0:'overwrite'});assert.equal(old.id,id);assert.equal(old.phone,'0123456789');assert.equal(old.address,'ที่อยู่, ไทย');assert.equal(s.projects[0].contractor,'ชื่อปรับใหม่');const out=App.parseCSVTable(App.masterCSV(s,'contractors'));assert(!out[0].includes('workspace_id'));assert(!out[0].includes('ID'));assert(!out[0].includes('เก็บเข้าคลัง'));const repeat=App.previewMasterCSV(s,'contractors',App.masterCSV(s,'contractors'));assert.equal(App.applyMasterCSV(s,'contractors',repeat,{0:'overwrite'}).updated,0);});
