test('legacy code-less jobs remain pending but new jobs require a unique work code',()=>{const s=importFixture();s.workNames=[{id:'J1',name:'งานเดิม',codeIds:[]}];s.workCodes=[];s.workTypes=[];App.assignMasterCodes(s);let p=App.previewMasterCSV(s,'workNames',App.masterCSV(s,'workNames'));assert.deepEqual(p[0].errors,[]);p=App.previewMasterCSV(s,'workNames','ชื่องาน,รหัสงาน\nงานใหม่,');assert(p[0].errors.length);p=App.previewMasterCSV(s,'workNames','ชื่องาน,รหัสงาน\nงานใหม่,12345');App.applyMasterCSV(s,'workNames',p);assert.equal(s.workNames[1].codeIds.length,1);p=App.previewMasterCSV(s,'workNames','ชื่องาน,รหัสงาน\nงานซ้ำรหัส,12345');assert(p[0].errors.length);});
