test('registry import reuses exact contractors and change badges survive identical reimports',()=>{const s=importFixture();s.contractors=[{id:'KEEP',name:'บริษัทเดิม',address:'ที่อยู่เดิม',phone:'0812345678'}];const r={contract:'X/2569',title:'โครงการ',start:'2026-01-01',end:'2026-02-01',duration:32,contractorRaw:'บริษัทเดิม'};let p=App.previewRegistryImport(s,[r],2569,'DOH'),result=App.applyRegistryImport(s,p);assert.equal(result.state.contractors.length,1);const record=result.state.contractRegistry.at(-1);assert.equal(record.contractorId,'KEEP');assert.equal(record.contractorNeedsReview,false);assert.equal(record.dataChange.kind,'new');p=App.previewRegistryImport(result.state,[{...r,id:record.id}],2569,'DOH');const again=App.applyRegistryImport(result.state,p,{0:'overwrite'});assert.equal(again.unchanged,1);assert.deepEqual(again.state,result.state);p=App.previewRegistryImport(result.state,[{...r,id:record.id,title:'แก้ชื่อ'}],2569,'DOH');const changed=App.applyRegistryImport(result.state,p,{0:'overwrite'});assert.equal(changed.state.contractRegistry.at(-1).dataChange.kind,'updated');assert.equal(changed.state.contractors[0].phone,'0812345678');assert.deepEqual(changed.state.reports,s.reports);});
